<script>
(function(){
'use strict';
const NS='http://www.w3.org/2000/svg',TAU=Math.PI*2;
const $=id=>document.getElementById(id);
const el=(tag,at,par)=>{const e=document.createElementNS(NS,tag);if(at)for(const k in at)e.setAttribute(k,at[k]);if(par)par.appendChild(e);return e;};
const rng=s=>()=>{s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};
const f=n=>Math.round(n*10)/10;
const f2=n=>n.toFixed(2);
const pt=p=>f(p[0])+','+f(p[1]);
const lerp=(a,b,t)=>a+(b-a)*t;
const frac=x=>x-Math.floor(x);

/* ---------- path helpers (all clockwise so unions never punch holes) ---------- */
const circ=(x,y,r)=>'M'+f(x-r)+','+f(y)+'a'+f(r)+','+f(r)+' 0 1,1 '+f(2*r)+',0a'+f(r)+','+f(r)+' 0 1,1 '+f(-2*r)+',0Z';
const ell=(x,y,rx,ry)=>'M'+f(x-rx)+','+f(y)+'a'+f(rx)+','+f(ry)+' 0 1,1 '+f(2*rx)+',0a'+f(rx)+','+f(ry)+' 0 1,1 '+f(-2*rx)+',0Z';
const blade=(x,y,h,lean,w)=>'M'+f(x-w)+','+f(y)+'Q'+f(x-w*.3+lean*.3)+','+f(y-h*.6)+' '+f(x+lean)+','+f(y-h)+'Q'+f(x+w*.5+lean*.5)+','+f(y-h*.5)+' '+f(x+w)+','+f(y)+'Z';
function tuft(x,y,n,h,w,r){let d='';for(let i=0;i<n;i++){const k=i-(n-1)/2;d+=blade(x+k*w*1.2,y,h*(.55+r()*.55),k*h*.28+(r()-.5)*h*.25,w);}return d;}
const cyp=(x,y,s)=>'M'+f(x)+','+f(y-s*2.7)+'C'+f(x+s*.6)+','+f(y-s*1.7)+' '+f(x+s*.55)+','+f(y-s*.3)+' '+f(x)+','+f(y)+'C'+f(x-s*.55)+','+f(y-s*.3)+' '+f(x-s*.6)+','+f(y-s*1.7)+' '+f(x)+','+f(y-s*2.7)+'Z';

/* ---------- scrolling layers ---------- */
const layers=[];
function layer(id,W,fac,drift){
  const g=$(id),copies=[-W,0,W].map(x=>el('g',{transform:'translate('+x+',0)'},g));
  const L={g,W,fac,drift:drift||0,add(tag,at){for(const c of copies)el(tag,at,c);}};
  layers.push(L);return L;
}

function mountains(L,o){
  const r=rng(o.seed),W=L.W,n=o.n,seg=W/n,B=o.bottom,P=[],V=[];
  for(let i=0;i<n;i++)P.push([(i+.5+(r()-.5)*.6)*seg,o.base-lerp(o.hMin,o.hMax,r())]);
  for(let i=0;i<n;i++){
    const a=P[i],b=P[(i+1)%n],bx=b[0]+(i===n-1?W:0);
    V.push([lerp(a[0],bx,.38+r()*.24),o.base-Math.min(o.base-a[1],o.base-b[1])*(.2+r()*.35)]);
  }
  const v0=[V[n-1][0]-W,V[n-1][1]];
  let d='M'+f(v0[0]-1)+','+B+'L'+f(v0[0]-1)+','+f(v0[1]);
  for(let i=0;i<n;i++)d+='L'+pt(P[i])+'L'+pt(V[i]);
  d+='L'+f(V[n-1][0])+','+B+'Z';
  L.add('path',{d:d,fill:o.fill});
  let ds='',dn='',dns='';
  for(let i=0;i<n;i++){
    const p=P[i],vl=i?V[i-1]:v0,vr=V[i],h=B-p[1];
    const j1=[p[0]-5-r()*10,p[1]+h*.28],j2=[p[0]+5+r()*10,p[1]+h*.55],j3=[p[0]-6-r()*14,B];
    ds+='M'+pt(p)+'L'+pt(j1)+'L'+pt(j2)+'L'+pt(j3)+'L'+f(vl[0])+','+B+'L'+pt(vl)+'Z';
    if(o.base-p[1]>o.snow){
      const s=.2+r()*.14,a=[lerp(p[0],vl[0],s),lerp(p[1],vl[1],s)],b=[lerp(p[0],vr[0],s),lerp(p[1],vr[1],s)],z=[];
      const amp=(b[0]-a[0])*.11;
      for(let k=1;k<6;k++)z.push([lerp(b[0],a[0],k/6)+(r()-.5)*4,lerp(b[1],a[1],k/6)+(k%2?1:-.35)*amp*(.7+r()*.6)]);
      dn+='M'+pt(p)+'L'+pt(b)+z.map(q=>'L'+pt(q)).join('')+'L'+pt(a)+'Z';
      dns+='M'+pt(p)+'L'+pt(z[2])+'L'+pt(z[3])+'L'+pt(z[4])+'L'+pt(a)+'Z';
    }
  }
  L.add('path',{d:ds,fill:o.shade,opacity:o.shadeOp});
  if(dn){L.add('path',{d:dn,fill:'#ffffff'});L.add('path',{d:dns,fill:o.snowShade});}
}

function hills(L,o){
  const r=rng(o.seed),W=L.W,comps=o.amps.map((a,i)=>[a,o.freqs[i],r()*TAU]);
  const y=x=>{let s=o.base;for(const c of comps)s+=c[0]*Math.sin(TAU*c[1]*x/W+c[2]);return s;};
  let d='M-1,'+o.bottom;
  for(let x=-1;x<W+1;x+=16)d+='L'+x+','+f(y(x));
  d+='L'+(W+1)+','+f(y(W+1))+'L'+(W+1)+','+o.bottom+'Z';
  L.add('path',{d:d,fill:o.fill});
  return y;
}

const FCOL=[['#ffffff','#ffd24d'],['#ff9fb4','#ffe38a'],['#ffd65c','#f2913d'],['#c3a6f5','#fff3c9']];
function flowers(L,items,stemCol,sw){
  const acc=FCOL.map(()=>({p:'',c:''}));let st='';
  for(const it of items){
    const x=it[0],y=it[1],h=it[2],s=it[3],k=it[4],cy=y-h;
    st+='M'+f(x)+','+f(y)+'q'+f(s*.8)+','+f(-h*.5)+' 0,'+f(-h);
    for(let j=0;j<5;j++){const a=j/5*TAU-1.57;acc[k].p+=circ(x+Math.cos(a)*s,cy+Math.sin(a)*s,s*.72);}
    acc[k].c+=circ(x,cy,s*.62);
  }
  L.add('path',{d:st,stroke:stemCol,'stroke-width':sw,fill:'none','stroke-linecap':'round'});
  acc.forEach((a,k)=>{if(a.p){L.add('path',{d:a.p,fill:FCOL[k][0]});L.add('path',{d:a.c,fill:FCOL[k][1]});}});
}

/* ---------- build the scene ---------- */
const W=2560;

// clouds
{
  const L=layer('clouds',W,.015,5),r=rng(7);let d='';
  for(let i=0;i<8;i++){
    const w=110+r()*150,x=i*320+r()*60,y=70+r()*190,h=w*.2;
    d+='M'+f(x+h/2)+','+f(y-h)+'h'+f(w-h)+'a'+f(h/2)+','+f(h/2)+' 0 0 1 0,'+f(h)+'h'+f(-(w-h))+'a'+f(h/2)+','+f(h/2)+' 0 0 1 0,'+f(-h)+'Z';
    d+=circ(x+w*.32,y-h*.95,w*.17)+circ(x+w*.56,y-h*1.15,w*.23)+circ(x+w*.76,y-h*.85,w*.14);
  }
  L.add('path',{d:d,fill:'#ffffff',opacity:.82});
}

// mountains
mountains(layer('mtFar',W,.05),{seed:12,n:7,base:470,hMin:150,hMax:300,bottom:525,snow:185,fill:'url(#gM1)',shade:'#5868ad',shadeOp:.24,snowShade:'#d3dcf2'});
mountains(layer('mtMid',W,.1),{seed:29,n:10,base:500,hMin:90,hMax:190,bottom:565,snow:160,fill:'url(#gM2)',shade:'#44558f',shadeOp:.26,snowShade:'#c9d4ee'});

// far hills with bush speckles
{
  const L=layer('hillFar',W,.16);
  const y=hills(L,{seed:21,base:452,amps:[14,9,5],freqs:[2,5,9],bottom:575,fill:'url(#gH1)'});
  const r=rng(5);let d='';
  for(let i=0;i<80;i++){const x=r()*W;d+=circ(x,y(x)+3+r()*32,2.5+r()*4);}
  L.add('path',{d:d,fill:'#5c9b90',opacity:.5});
}

// near hills with trees
{
  const L=layer('hillNear',W,.3);
  const y=hills(L,{seed:33,base:500,amps:[12,8,4],freqs:[3,4,8],bottom:605,fill:'url(#gH2)'});
  const r=rng(11);let d1='',d2='';
  for(let i=0;i<38;i++){
    const x=r()*W,yy=y(x)+4+r()*24,s=6+r()*7;
    if(r()<.45)d1+=cyp(x,yy,s);
    else{d1+='M'+f(x-1.2)+','+f(yy)+'v'+f(-s)+'h2.4v'+f(s)+'Z'+circ(x,yy-s*1.5,s*.9);d2+=circ(x+s*.25,yy-s*1.7,s*.45);}
  }
  L.add('path',{d:d1,fill:'#3f8a63'});
  L.add('path',{d:d2,fill:'#5aa878',opacity:.8});
}

// back meadow
{
  const L=layer('fieldBack',W,.55);
  const y=hills(L,{seed:41,base:548,amps:[5,3],freqs:[2,5],bottom:612,fill:'url(#gF1)'});
  const r=rng(43),ds=['',''];
  for(let i=0;i<130;i++){const x=r()*W;ds[i%2]+=tuft(x,y(x)+4+r()*13,3,4+r()*4,1.1,r);}
  L.add('path',{d:ds[0],fill:'#86c160'});
  L.add('path',{d:ds[1],fill:'#c2e894'});
  const fd=['','',''];
  for(let i=0;i<70;i++){const x=r()*W;fd[i%3]+=circ(x,y(x)+3+r()*14,1.2+r()*.9);}
  L.add('path',{d:fd[0],fill:'#ffffff'});
  L.add('path',{d:fd[1],fill:'#ffb3c4'});
  L.add('path',{d:fd[2],fill:'#ffe07a'});
}
{
  const L=layer('fieldMid',W,.78),r=rng(47),ds=['',''],items=[];
  for(let i=0;i<110;i++){const x=r()*W;ds[i%2]+=tuft(x,563+r()*10,3,6+r()*6,1.4,r);}
  L.add('path',{d:ds[0],fill:'#7dbb5c'});
  L.add('path',{d:ds[1],fill:'#b4e085'});
  for(let i=0;i<26;i++)items.push([r()*W,564+r()*9,6+r()*5,1.7+r()*.6,(r()*4)|0]);
  flowers(L,items,'#6aa84f',1);
}

// the trail the alpaca walks on (scrolls exactly with the feet)
{
  const L=layer('trail',W,1),r=rng(31);
  const yT=x=>579+2.5*Math.sin(TAU*3*x/W+1)+1.5*Math.sin(TAU*8*x/W+2);
  let d='M-1,672',d2='';
  for(let x=-1;x<W+1;x+=16)d+='L'+x+','+f(yT(x));
  d+='L'+(W+1)+','+f(yT(W+1))+'L'+(W+1)+',672Z';
  L.add('path',{d:d,fill:'#edd6a5'});
  d2='M-1,'+f(yT(-1));
  for(let x=15;x<W+1;x+=16)d2+='L'+x+','+f(yT(x));
  for(let x=W+1;x>=-1;x-=16)d2+='L'+x+','+f(yT(x)+5+2*Math.sin(x*.05));
  L.add('path',{d:d2+'Z',fill:'#d9bd84',opacity:.75});
  const sd=['',''];
  for(let i=0;i<80;i++){const x=r()*W,y=588+r()*46,l=8+r()*26;sd[i%2]+='M'+f(x)+','+f(y)+'h'+f(l);}
  L.add('path',{d:sd[0],stroke:'#dfc590','stroke-width':2.2,'stroke-linecap':'round',fill:'none',opacity:.8});
  L.add('path',{d:sd[1],stroke:'#f8ebc9','stroke-width':2.2,'stroke-linecap':'round',fill:'none',opacity:.9});
  let pd='',ph='';
  for(let i=0;i<50;i++){const x=r()*W,y=588+r()*46,s=1.6+r()*2.6;pd+=ell(x,y,s*1.5,s);ph+=ell(x-.4*s,y-.35*s,s*.8,s*.45);}
  L.add('path',{d:pd,fill:'#c5a878'});
  L.add('path',{d:ph,fill:'#e8d6ae'});
  let rd='',rh='';
  for(let i=0;i<6;i++){
    const x=(i+.2+r()*.6)*W/6,y=yT(x)+4,w=9+r()*10,h=7+r()*7;
    rd+='M'+f(x-w)+','+f(y)+'C'+f(x-w)+','+f(y-h*.9)+' '+f(x-w*.3)+','+f(y-h*1.2)+' '+f(x+w*.1)+','+f(y-h)+'C'+f(x+w*.7)+','+f(y-h*.9)+' '+f(x+w)+','+f(y-h*.4)+' '+f(x+w)+','+f(y)+'Z';
    rh+='M'+f(x-w*.7)+','+f(y-h*.5)+'C'+f(x-w*.5)+','+f(y-h)+' '+f(x)+','+f(y-h*1.05)+' '+f(x+w*.3)+','+f(y-h*.8)+'C'+f(x)+','+f(y-h*.8)+' '+f(x-w*.4)+','+f(y-h*.6)+' '+f(x-w*.7)+','+f(y-h*.5)+'Z';
  }
  L.add('path',{d:rd,fill:'#aaa59c'});
  L.add('path',{d:rh,fill:'#d6d1c7'});
  const td=['','',''],items=[];
  for(let i=0;i<150;i++){
    const x=r()*W,q=r(),k=q<.42?0:q<.78?1:2;
    td[k]+=tuft(x,yT(x)+1+r()*4,3+((r()*3)|0),8+r()*10,1.7,r);
  }
